//! Opens the synthetic public corpus (tests/corpus/public, generated by
//! scripts/make-fixtures.mjs) through the public API only.
#![allow(
    clippy::expect_used,
    clippy::panic,
    reason = "test helpers: a failed expectation is a test failure"
)]

use std::fs::File;
use std::path::PathBuf;

use pdf_syntax::{
    Budget, CancellationToken, IndirectValue, MemorySource, Object, ObjectId, PdfFile,
    ResourceLimits, Version,
};

fn open(name: &str) -> PdfFile<MemorySource> {
    let path = PathBuf::from(env!("CARGO_MANIFEST_DIR"))
        .join("../../tests/corpus/public")
        .join(name);
    let limits = ResourceLimits::default();
    let file = File::open(&path).expect("fixture present");
    let size = file.metadata().map(|m| m.len()).ok();
    let source = MemorySource::from_reader(file, size, &limits).expect("readable fixture");
    let mut budget = Budget::new(limits, CancellationToken::new());
    PdfFile::open(source, &mut budget).expect("valid fixture")
}

fn resolve(file: &PdfFile<MemorySource>, number: u32) -> IndirectValue {
    let mut budget = Budget::new(ResourceLimits::default(), CancellationToken::new());
    file.resolve(
        ObjectId {
            number,
            generation: 0,
        },
        &mut budget,
    )
    .expect("resolvable object")
}

fn content_of(file: &PdfFile<MemorySource>) -> Vec<u8> {
    let IndirectValue::Stream(stream) = resolve(file, 4) else {
        panic!("object 4 is the content stream");
    };
    file.stream_data(&stream).expect("in bounds").into_owned()
}

#[test]
fn minimal_fixture() {
    let file = open("minimal.pdf");
    assert_eq!(file.version(), Version { major: 1, minor: 4 });
    assert_eq!(file.revisions(), 1);
    assert_eq!(file.entries().count(), 6);
    let root = file.root().expect("root");
    let IndirectValue::Object(Object::Dictionary(catalog)) = resolve(&file, root.number) else {
        panic!("catalog dictionary");
    };
    assert_eq!(
        catalog.get(b"Type"),
        Some(&Object::Name(b"Catalog".to_vec()))
    );
    for number in 1..=5 {
        assert!(!matches!(
            resolve(&file, number),
            IndirectValue::Object(Object::Null)
        ));
    }
    assert_eq!(
        content_of(&file),
        b"BT /F1 24 Tf 72 770 Td (CastlePDF minimal fixture) Tj ET"
    );
}

#[test]
fn incremental_fixture_reads_the_newest_revision() {
    let file = open("incremental.pdf");
    assert_eq!(file.revisions(), 2);
    assert_eq!(
        file.trailer().get(b"Prev").and_then(Object::as_integer),
        Some(425)
    );
    assert_eq!(
        content_of(&file),
        b"BT /F1 24 Tf 72 770 Td (CastlePDF updated revision) Tj ET"
    );
}

#[test]
fn flate_fixture_decodes_content_and_predicted_data() {
    let file = open("flate.pdf");
    let mut budget = Budget::new(ResourceLimits::default(), CancellationToken::new());
    let decoded = |number| {
        let IndirectValue::Stream(stream) = resolve(&file, number) else {
            panic!("object {number} is a stream");
        };
        let mut budget = Budget::new(ResourceLimits::default(), CancellationToken::new());
        file.decoded_stream_data(&stream, &mut budget)
            .expect("decodable")
    };
    // /Filter 6 0 R: the filter name is resolved through the table.
    assert_eq!(
        decoded(4),
        b"BT /F1 24 Tf 72 770 Td (CastlePDF Flate fixture) Tj ET"
    );
    assert_eq!(decoded(7), vec![1, 2, 3, 4, 2, 4, 6, 8, 3, 6, 9, 12]);
    // Unfiltered streams of other fixtures decode to their raw bytes.
    let minimal = open("minimal.pdf");
    let IndirectValue::Stream(stream) = resolve(&minimal, 4) else {
        panic!("content stream");
    };
    assert_eq!(
        minimal
            .decoded_stream_data(&stream, &mut budget)
            .expect("raw"),
        minimal.stream_data(&stream).expect("raw").into_owned()
    );
}
